package com.erudit.quiz.service;import com.erudit.quiz.model.QuizModels.*;import com.erudit.quiz.repository.QuizRepository;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.beans.factory.ObjectProvider;import org.springframework.beans.factory.annotation.Autowired;import com.erudit.integration.InternalClients.AiClient;import com.erudit.integration.InternalContracts.AiRequest;import com.erudit.integration.ResilientExecutor;import io.github.resilience4j.circuitbreaker.CircuitBreakerRegistry;
@Service public class QuizService {private final QuizRepository repository;private final ObjectProvider<AiClient> ai;private final CircuitBreakerRegistry breakers;public QuizService(QuizRepository repository){this.repository=repository;this.ai=null;this.breakers=null;}@Autowired public QuizService(QuizRepository repository,ObjectProvider<AiClient> ai,CircuitBreakerRegistry breakers){this.repository=repository;this.ai=ai;this.breakers=breakers;}
 public List<Quiz> list(){return repository.list();} public Quiz daily(){return repository.daily();}
 @Transactional public Quiz create(String title,String prompt,List<String> options,int correct,String hint){AiClient client=ai==null?null:ai.getIfAvailable();String sourcePrompt=prompt;if(client!=null){var generated=ResilientExecutor.execute(breakers.circuitBreaker("ai"),()->client.quiz(new AiRequest(title,sourcePrompt)),()->null);if(generated!=null&&generated.options()!=null&&generated.options().size()>=2&&generated.correctOption()>=0&&generated.correctOption()<generated.options().size()){prompt=generated.question();options=generated.options();correct=generated.correctOption();}}if(options==null||correct<0||correct>=options.size())throw new IllegalArgumentException("Correct option is out of range");return repository.create(title,prompt,options,correct,hint);}
 @Transactional public Attempt start(UUID quiz,UUID user){return repository.start(quiz,user==null?UUID.fromString("00000000-0000-0000-0000-000000000001"):user);}
 @Transactional public Hint hint(UUID id){Attempt v=repository.hint(repository.attempt(id));return new Hint(repository.question(v.quizId()).hint(),2-v.hintsUsed());}
 @Transactional public Attempt submit(UUID id,int option){Attempt v=repository.attempt(id);if(!"STARTED".equals(v.status()))throw new IllegalStateException("Quiz already submitted");return repository.finish(v,repository.question(v.quizId()).correct()==option?1:0);}
 public record Hint(String text,int remaining){}
}
